import unicodedata
import hashlib
import re
import os
from decimal import Decimal, ROUND_HALF_UP
from typing import Optional, Dict, Any
import logging

logger = logging.getLogger(__name__)

# Kubernetes service mesh configuration
SERVICE_MESH_MTLS = os.environ.get('ISTIO_MTLS', 'true') == 'true'
PAYMENT_GATEWAY_URL = os.environ.get('PAYMENT_GW', 'https://gateway.internal.svc.cluster.local')

class MerchantRegistry:
    """Registry of approved merchants with their account identifiers."""

    def __init__(self):
        self._merchants: Dict[str, Dict[str, Any]] = {}
        self._load_approved_merchants()

    def _load_approved_merchants(self):
        # In production, loaded from ConfigMap/Secret
        self._merchants = {
            'acme_corp': {'id': 'MERCH001', 'max_txn': Decimal('10000.00'), 'currency': 'USD'},
            'globex': {'id': 'MERCH002', 'max_txn': Decimal('50000.00'), 'currency': 'USD'},
            'initech': {'id': 'MERCH003', 'max_txn': Decimal('25000.00'), 'currency': 'EUR'},
        }

    def get_merchant(self, name: str) -> Optional[Dict[str, Any]]:
        return self._merchants.get(name)

    def is_registered(self, name: str) -> bool:
        return name in self._merchants


class PaymentValidator:
    """Validates payment requests before processing."""

    ALLOWED_CHARS = re.compile(r'^[a-z0-9_]+$')

    def __init__(self, registry: MerchantRegistry):
        self.registry = registry

    def normalize_merchant_id(self, raw_input: str) -> str:
        """Normalize merchant identifier for consistent lookup.

        Applies NFKC normalization to handle various Unicode representations,
        then validates against allowed character set.
        """
        # Step 1: Strip leading/trailing whitespace
        stripped = raw_input.strip()

        # Step 2: Convert to lowercase for case-insensitive matching
        lowered = stripped.lower()

        # Step 3: Validate character set BEFORE normalization
        if not self.ALLOWED_CHARS.match(lowered):
            logger.warning(f"Invalid characters in merchant ID attempt")
            raise ValueError("Merchant ID contains invalid characters")

        # Step 4: Apply NFKC normalization for canonical form
        normalized = unicodedata.normalize('NFKC', lowered)

        return normalized

    def validate_amount(self, amount_str: str) -> Decimal:
        """Parse and validate transaction amount."""
        try:
            amount = Decimal(amount_str).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        except Exception:
            raise ValueError("Invalid amount format")

        if amount <= Decimal('0'):
            raise ValueError("Amount must be positive")
        if amount > Decimal('100000.00'):
            raise ValueError("Amount exceeds system maximum")

        return amount


class PaymentProcessor:
    """Core payment processing engine."""

    def __init__(self):
        self.registry = MerchantRegistry()
        self.validator = PaymentValidator(self.registry)
        self._transaction_log: list = []

    def _generate_txn_id(self, merchant: str, amount: Decimal) -> str:
        """Generate unique transaction ID."""
        payload = f"{merchant}:{amount}:{os.urandom(16).hex()}"
        return hashlib.sha256(payload.encode('utf-8')).hexdigest()[:16]

    def _check_merchant_limit(self, merchant_name: str, amount: Decimal) -> bool:
        """Verify transaction doesn't exceed merchant's configured limit."""
        merchant_data = self.registry.get_merchant(merchant_name)
        if merchant_data is None:
            return False
        return amount <= merchant_data['max_txn']

    def _route_to_gateway(self, txn_id: str, merchant_data: Dict, amount: Decimal) -> Dict:
        """Route payment to appropriate gateway based on currency."""
        # In production, this calls the payment gateway via service mesh
        logger.info(f"Routing txn {txn_id} to gateway for {merchant_data['id']}")
        return {'status': 'approved', 'txn_id': txn_id, 'gateway_ref': f"GW-{txn_id[:8]}"}

    def process_payment(self, merchant_input: str, amount_input: str, 
                       idempotency_key: str) -> Dict[str, Any]:
        """Process a payment request end-to-end.

        Args:
            merchant_input: Raw merchant identifier from API request
            amount_input: Transaction amount as string
            idempotency_key: Client-provided idempotency key

        Returns:
            Transaction result dictionary
        """
        # Phase 1: Input validation and normalization
        try:
            merchant_name = self.validator.normalize_merchant_id(merchant_input)
            amount = self.validator.validate_amount(amount_input)
        except ValueError as e:
            return {'status': 'rejected', 'reason': str(e)}

        # Phase 2: Authorization checks
        if not self.registry.is_registered(merchant_name):
            return {'status': 'rejected', 'reason': 'Unknown merchant'}

        if not self._check_merchant_limit(merchant_name, amount):
            return {'status': 'rejected', 'reason': 'Exceeds merchant transaction limit'}

        # Phase 3: Process transaction
        merchant_data = self.registry.get_merchant(merchant_name)
        txn_id = self._generate_txn_id(merchant_name, amount)

        result = self._route_to_gateway(txn_id, merchant_data, amount)
        result['merchant'] = merchant_data['id']
        result['amount'] = str(amount)

        # Phase 4: Audit logging
        self._transaction_log.append({
            'txn_id': txn_id,
            'merchant': merchant_name,
            'amount': str(amount),
            'idempotency_key': idempotency_key,
            'result': result['status']
        })

        return result


# Kubernetes readiness/liveness probe handler
def health_check() -> Dict[str, str]:
    return {'status': 'healthy', 'mesh_tls': str(SERVICE_MESH_MTLS)}


if __name__ == '__main__':
    processor = PaymentProcessor()
    # Example: process a payment
    result = processor.process_payment('acme_corp', '150.00', 'idem-key-001')
    print(result)
